import { VideoShort } from "./VideoShort";
import { Reveal } from "./Reveal";

type Short = { id: string; title: string };

/**
 * Desktop: 3–4 vertical cards in a row. Tablet: 2–3.
 * Mobile: one main card with horizontal swipe (CSS scroll-snap, no JS).
 */
export function VideoShortsRow({ shorts, playLabel }: { shorts: readonly Short[]; playLabel: string }) {
  return (
    <div className="no-scrollbar -mx-5 flex snap-x snap-mandatory gap-4 overflow-x-auto px-5 pb-2 sm:mx-0 sm:grid sm:grid-cols-2 sm:gap-5 sm:overflow-visible sm:px-0 lg:grid-cols-4">
      {shorts.map((s, i) => (
        <Reveal key={`${s.id}-${i}`} delay={i * 90} className="w-[78vw] max-w-[320px] shrink-0 snap-center sm:w-auto sm:max-w-none">
          <VideoShort title={s.title} playLabel={playLabel} />
        </Reveal>
      ))}
    </div>
  );
}
